export function uiText(language: AppLanguage, key: string): string {
  return ui[language][key] || ui.en[key] || key;
}

export function symptomText(language: AppLanguage, value: string, fallback: string): string {
  return symptomLabels[language][value] || symptomLabels.en[value] || fallback;
}
